// Imports
import { describe, it, beforeEach, vi } from 'vitest'
import chai from 'chai'
import chaiAsPromised from 'chai-as-promised'
const expect = chai.expect;
chai.use(chaiAsPromised);

describe('invoiceId', function() {
	let parseInvoiceId: any;
	beforeEach(async () => {
		vi.resetModules();
		({ parseInvoiceId } = await import("../src/invoiceId"));
	});

	it("month value outside 01-12 (13) is rejected as malformed, even though the digit count is correct", async () => {
		// Sekcja 2 / Format: MM musi byc dokladnie dwiema cyframi z zakresu 01-12.
		const raw = "FV/1999/13/0000";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`malformed invoice id`)
	})

	it("arbitrary string that does not match the FV/RRRR/MM/NNNN pattern is rejected as malformed", async () => {
		// Sekcja 2 / Format
		const raw = "Y;U=1RGePKms,YuVfGiPP\n/,`iq`Z2±lG\"D@6R\t]r+R±S}@jec$N'qz3N}c8;DbA";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`malformed invoice id`)
	})

	it("plain string unrelated to the invoice id format is rejected as malformed", async () => {
		// Sekcja 2 / Format
		const raw = "valueOf";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`malformed invoice id`)
	})

	it("leading whitespace is trimmed before parsing; an object with a trim() method is still not a string", async () => {
		// Sekcja 2 / Format: biale znaki na poczatku i koncu sa ignorowane.
		const raw = " FV/2026/09/0042";
		const parseInvoiceIdReturnValue = await parseInvoiceId(raw)
		const trim = () => {};
		const raw1 = {
			"trim": trim
		}

		expect(JSON.parse(JSON.stringify(parseInvoiceIdReturnValue))).to.deep.equal({"year":2026,"month":9,"seq":42})
		// Sekcja 2 / Walidacja: typeof raw !== "string" -> TypeError, nawet gdy obiekt ma metode trim().
		await expect((async () => {
			await parseInvoiceId(raw1)
		})()).to.be.rejectedWith(`invoice id must be a string`)
	})

	it("year just below the lower inclusive bound (2000) is rejected as out of range", async () => {
		// Sekcja 2 / Walidacja: rok poza zakresem 2000-2100.
		const raw = "FV/1999/12/0001";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`year out of supported range`)
	})

	it("an object exposing a trim() method is not a string and is rejected with TypeError", async () => {
		// Sekcja 2 / Walidacja: typeof raw !== "string" fires before any format check.
		const trim = () => {};
		const raw = {
			"trim": trim
		}

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`invoice id must be a string`)
	})

	it("year below the lower bound (1999) is rejected as out of range (duplicate boundary case)", async () => {
		// Sekcja 2 / Walidacja: rok poza zakresem 2000-2100.
		const raw = "FV/1999/12/0001";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`year out of supported range`)
	})

	it("an object exposing a trim() method is not a string and is rejected with TypeError (duplicate)", async () => {
		// Sekcja 2 / Walidacja: typeof raw !== "string" fires before any format check.
		const trim = () => {};
		const raw = {
			"trim": trim
		}

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`invoice id must be a string`)
	})

	it("an array is not a string and is rejected with TypeError", async () => {
		// Sekcja 2 / Walidacja: typeof [] === "object", nie "string".
		const arrayElement = {}
		const arrayElement1 = "weight must be positive";
		const raw = [arrayElement, arrayElement1]

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`invoice id must be a string`)
	})

	it("an array is not a string and is rejected with TypeError (duplicate)", async () => {
		// Sekcja 2 / Walidacja: typeof [] === "object", nie "string".
		const arrayElement = {}
		const arrayElement1 = "weight must be positive";
		const raw = [arrayElement, arrayElement1]

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`invoice id must be a string`)
	})

	it("whitespace immediately after the FV/ prefix (inside the identifier) is rejected as malformed", async () => {
		// Sekcja 2 / Format: biale znaki wewnatrz identyfikatora nie sa dozwolone
		// (tylko wiodace/koncowe biale znaki calego stringa sa ignorowane).
		const raw = "FV/ 2026/09/0042";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`malformed invoice id`)
	})

	it("sequence number exactly 0000 is rejected as zero even though it matches the format", async () => {
		// Sekcja 2 / Walidacja: numer kolejny rowny 0000 -> RangeError.
		const raw = "FV/2026/09/0000";

		await expect((async () => {
			await parseInvoiceId(raw)
		})()).to.be.rejectedWith(`sequence number must not be zero`)
	})
})

// Imports
import { describe, it, beforeEach, vi } from 'vitest'
import chai from 'chai'
import chaiAsPromised from 'chai-as-promised'
const expect = chai.expect;
chai.use(chaiAsPromised);

describe('loyalty', function() {
	let awardPoints: any;
	let Cart: any;
	beforeEach(async () => {
		vi.resetModules();
		({ awardPoints } = await import("../src/loyalty"));
		({ Cart } = await import("../src/cart"));
	});

	it("negative orderValuePLN triggers RangeError even with a valid lifetimeSpendPLN", async () => {
		const orderValuePLN = -576;
		const lifetimeSpendPLN = 333.4674790543404;

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("banker's rounding: 29.99/10 rounds to 3, not the code's floor(2) (Sekcja 3: Punkty lojalnosciowe / Przelicznik)", async () => {
		const orderValuePLN = 29.99;
		const lifetimeSpendPLN = 2000;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const orderValuePLN1 = 584;
		const orderValuePLN2 = 29.99;
		const awardPointsReturnValue1 = await awardPoints(orderValuePLN1, orderValuePLN2)
		const orderValuePLN3 = 10.0001;
		const orderValuePLN4 = 29.99;
		const awardPointsReturnValue2 = await awardPoints(orderValuePLN3, orderValuePLN4)

		// DIV-LOY-1: 29.99/10 = 2.999 -> banker's rounding gives 3; code's Math.floor gives 2. Left failing.
		expect(awardPointsReturnValue).to.equal(3)
		expect(awardPointsReturnValue1).to.equal(58)
		expect(awardPointsReturnValue2).to.equal(1)
	})

	it("negative lifetimeSpendPLN triggers RangeError with a large orderValuePLN", async () => {
		const orderValuePLN = 30000;
		const lifetimeSpendPLN = -9;

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("exact multiple of 10 (1800) needs no rounding correction; non-finite string orderValuePLN triggers TypeError", async () => {
		const orderValuePLN = 1800;
		const lifetimeSpendPLN = 65;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const orderValuePLN1 = 1800;
		const lifetimeSpendPLN1 = 65;
		const awardPointsReturnValue1 = await awardPoints(orderValuePLN1, lifetimeSpendPLN1)
		const orderValuePLN2 = "FV/2026 /09/0042";
		const lifetimeSpendPLN2 = 65;

		expect(awardPointsReturnValue).to.equal(180)
		expect(awardPointsReturnValue1).to.equal(180)
		await expect((async () => {
			await awardPoints(orderValuePLN2, lifetimeSpendPLN2)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("exact multiple of 10 (100) needs no rounding correction; null/undefined args trigger TypeError", async () => {
		const orderValuePLN = 100;
		const lifetimeSpendPLN = 52;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const orderValuePLN1 = null;
		const lifetimeSpendPLN1 = undefined;

		expect(awardPointsReturnValue).to.equal(10)
		await expect((async () => {
			await awardPoints(orderValuePLN1, lifetimeSpendPLN1)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("banker's rounding under VIP multiplier: 217/10 rounds to 22, doubled to 44, not the code's floor-then-double 42 (Sekcja 3: Punkty lojalnosciowe / Przelicznik); negative lifetimeSpendPLN triggers RangeError", async () => {
		const orderValuePLN = 217;
		const lifetimeSpendPLN = 5000.01;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const lifetimeSpendPLN1 = 5000.01;
		const lifetimeSpendPLN2 = -947.3214338669724;

		// DIV-LOY-1: 217/10 = 21.7 -> banker's rounding gives 22 -> VIP doubles to 44;
		// code's Math.floor gives 21 -> doubled to 42. Left failing.
		expect(awardPointsReturnValue).to.equal(44)
		await expect((async () => {
			await awardPoints(lifetimeSpendPLN1, lifetimeSpendPLN2)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("malformed string lifetimeSpendPLN triggers TypeError", async () => {
		const orderValuePLN = 27;
		const lifetimeSpendPLN = "HD%[1Rl\n'3z[^R]dz<>5j]X`A>0F2'Vke%ui/eSH4t&=ar%xP±Jl1sVc<gjihfQc2,Eu[Ezj4bg ~l<cH:\t &&uZ4.%§I^n±4N*";

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("banker's rounding: 447/10 rounds to 45, not the code's floor(44) (Sekcja 3: Punkty lojalnosciowe / Przelicznik); negative orderValuePLN triggers RangeError", async () => {
		const orderValuePLN = 447;
		const lifetimeSpendPLN = 274;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const orderValuePLN1 = 2700;
		const lifetimeSpendPLN1 = -646.799514010976;

		// DIV-LOY-1: 447/10 = 44.7 -> banker's rounding gives 45; code's Math.floor gives 44. Left failing.
		expect(awardPointsReturnValue).to.equal(45)
		await expect((async () => {
			await awardPoints(orderValuePLN1, lifetimeSpendPLN1)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("non-finite lifetimeSpendPLN (plain object) triggers TypeError even though orderValuePLN is also invalid (finite check runs first)", async () => {
		const orderValuePLN = -930.8228607049024;
		const lifetimeSpendPLN = {}

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("near-multiples of 10 (554.69, 41.6) need no rounding correction; Cart.add rejects a non-integer priceGrosz", async () => {
		const orderValuePLN = 554.6915953798318;
		const lifetimeSpendPLN = 41.6;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const lifetimeSpendPLN1 = 41.6;
		const lifetimeSpendPLN2 = 41.6;
		const awardPointsReturnValue1 = await awardPoints(lifetimeSpendPLN1, lifetimeSpendPLN2)
		const anon2 = "FV2026090042";
		const anon3 = new Cart(anon2)
		const sku = () => {};
		const orderValuePLN1 = 554.6915953798318;
		const qty = 3;
		const anon4 = null;
		const anon5 = null;

		expect(awardPointsReturnValue).to.equal(55)
		expect(awardPointsReturnValue1).to.equal(4)
		await expect((async () => {
			await anon3.add(sku, orderValuePLN1, qty, anon4, anon5)
		})()).to.be.rejectedWith(`price must be a non-negative integer of grosz`)
	})

	it("negative orderValuePLN triggers RangeError regardless of a positive lifetimeSpendPLN", async () => {
		const orderValuePLN = -779.5644760656457;
		const lifetimeSpendPLN = 626.4817315750338;

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("non-numeric (array) orderValuePLN triggers TypeError", async () => {
		const arrayElement = 50;
		const arrayElement1 = undefined;
		const arrayElement2 = 23.2;
		const arrayElement3 = [arrayElement1, arrayElement2]
		const arrayElement4 = undefined;
		const arrayElement5 = -385.46346303594146;
		const arrayElement6 = [arrayElement4, arrayElement5]
		const arrayElement7 = "FV/2026/9/0042";
		const arrayElement8 = null;
		const orderValuePLN = [arrayElement, arrayElement3, arrayElement6, arrayElement7, arrayElement8]
		const lifetimeSpendPLN = 220;

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("lifetimeSpendPLN as a Cart instance (non-finite) triggers TypeError; finite check runs before the negativity check on orderValuePLN", async () => {
		const orderValuePLN = -41.11372416529059;
		const anon = false;
		const lifetimeSpendPLN = new Cart(anon)

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})

	it("negative orderValuePLN triggers RangeError with a large positive lifetimeSpendPLN", async () => {
		const orderValuePLN = -35;
		const lifetimeSpendPLN = 100;

		await expect((async () => {
			await awardPoints(orderValuePLN, lifetimeSpendPLN)
		})()).to.be.rejectedWith(`amounts must not be negative`)
	})

	it("cap applies after VIP doubling: 49980.09/10 rounds to 4998, doubled to 9996, capped at 5000 (Sekcja 3: Punkty lojalnosciowe / Limit); boolean lifetimeSpendPLN triggers TypeError", async () => {
		const orderValuePLN = 49980.09527164245;
		const lifetimeSpendPLN = 40000;
		const awardPointsReturnValue = await awardPoints(orderValuePLN, lifetimeSpendPLN)
		const orderValuePLN1 = 485.8335840188465;
		const lifetimeSpendPLN1 = false;

		expect(awardPointsReturnValue).to.equal(5000)
		await expect((async () => {
			await awardPoints(orderValuePLN1, lifetimeSpendPLN1)
		})()).to.be.rejectedWith(`amounts must be finite numbers`)
	})
})

// Imports
import { describe, it, beforeEach, vi } from 'vitest'
import chai from 'chai'
import chaiAsPromised from 'chai-as-promised'
const expect = chai.expect;
chai.use(chaiAsPromised);

describe('pricing', function() {
	let calculateShipping: any;
	let Cart: any;
	beforeEach(async () => {
		vi.resetModules();
		({ calculateShipping } = await import("../src/pricing"));
		({ Cart } = await import("../src/cart"));
	});

	it("non-finite weight (string) throws TypeError before zone/premium are inspected", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 1 (weightKg nie jest liczba skonczona)
		const weightKg = "PLN";
		const zone = "_u,%3pJ|'w@2<lOt?C^5}}XC:p+RFtp+~w&~ltp/[;8H~jfMLlur)32du6nNwg";
		const isPremium = true;

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight must be a finite number`)
	})

	it("weight above the 100kg carrier limit throws RangeError", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 3 (weightKg > 100)
		const weightKg = 6997;
		const zone = "X<2\\S~zi\\%ujRoH]906ae_L*/dl~ABt\"t-=842B5|`!=_)m\"=<7jil_s#f[T&N4G-'v-g)tAao4sQSv§+";
		const isPremium = false;

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight above carrier limit`)
	})

	it("unrecognized zone falls back to default 79 PLN rate, +15 surcharge (>10kg), then premium discount; weight above limit still rejected", async () => {
		// SPEC.md sekcja 1: stawka bazowa (inna wartosc -> 79), doplata wagowa (>10kg -> +15), rabat premium (*0.8)
		// (79 + 15) * 0.8 = 75.2
		const weightKg = 11;
		const zone = "1C[EgrcJl±Ok>L]-3,t&sw;";
		const isPremium = true;
		const calculateShippingReturnValue = await calculateShipping(weightKg, zone, isPremium)
		const weightKg1 = 6997;
		const zone1 = "2J3U±)Mmi|3{HBD/in)ix=|B<J§";
		const isPremium1 = true;

		expect(calculateShippingReturnValue).to.equal(75.2)
		await expect((async () => {
			await calculateShipping(weightKg1, zone1, isPremium1)
		})()).to.be.rejectedWith(`weight above carrier limit`)
	})

	it("default zone with >10kg surcharge and premium discount; passing the boolean isPremium flag itself as weight is non-finite", async () => {
		// SPEC.md sekcja 1: (79 + 15) * 0.8 = 75.2
		const weightKg = 12;
		const zone = " HALF";
		const isPremium = true;
		const calculateShippingReturnValue = await calculateShipping(weightKg, zone, isPremium)
		const isPremium1 = true;
		const zone1 = "Q§UnC.§!:XtX7Tnh:8h,}vWZ+\\g7V:C[L9ql:ui\n:.{{%v\nC((±±g";
		const isPremium2 = true;

		expect(calculateShippingReturnValue).to.equal(75.2)
		// weightKg argument here is `isPremium1` (a boolean) - Number.isFinite(true) === false
		await expect((async () => {
			await calculateShipping(isPremium1, zone1, isPremium2)
		})()).to.be.rejectedWith(`weight must be a finite number`)
	})

	it("negative weight is rejected as non-positive regardless of zone/premium (superfluous 4th arg trimmed)", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 2 (weightKg <= 0)
		const weightKg = -539;
		const zone = "L\"8cL1zIHr;oH'W}BJF$ks,MJ`\\UOp75f-VU^\\InRTejBEtPQ\\\n6Q1UO^s]hi| Y2| k±Dg\"\"TlY";
		const isPremium = "sku not in cart";

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight must be positive`)
	})

	it("weight <=10kg has no surcharge in default zone; non-boolean truthy isPremium value still triggers the premium discount", async () => {
		// SPEC.md sekcja 1: doplata wagowa (do 10 kg wlacznie -> brak), stawka bazowa (inna wartosc -> 79)
		// Second call passes isPremium1 = 26 (not strictly `true`, but truthy): code applies the
		// discount via `if (isPremium)`. isPremium is documented as never validated, so this
		// out-of-type-domain truthy value is not a spec violation, just an untyped-JS edge case.
		const weightKg = 9;
		const zone = "half";
		const isPremium = false;
		const calculateShippingReturnValue = await calculateShipping(weightKg, zone, isPremium)
		const weightKg1 = 9;
		const zone1 = "FV/2026/009/0042";
		const isPremium1 = 26;
		const calculateShippingReturnValue1 = await calculateShipping(weightKg1, zone1, isPremium1)

		expect(calculateShippingReturnValue).to.equal(79)
		expect(calculateShippingReturnValue1).to.equal(63.2)
	})

	it("default zone with >10kg surcharge and premium discount; default zone with >30kg surcharge and premium discount (superfluous args trimmed)", async () => {
		// SPEC.md sekcja 1: (79 + 15) * 0.8 = 75.2 ; (79 + 40) * 0.8 = 95.2
		const weightKg = 12;
		const zone = "$V!g}J+S~vP{W>OI:A";
		const isPremium = true;
		const calculateShippingReturnValue = await calculateShipping(weightKg, zone, isPremium)
		const weightKg1 = 75;
		const zone1 = "RXY/cair'§g[cV:x~}rZ-Cp?rVh6X6!NksY'R±bi!\ti§%§$\\7xRedx";
		const isPremium1 = true;
		const calculateShippingReturnValue1 = await calculateShipping(weightKg1, zone1, isPremium1)

		expect(calculateShippingReturnValue).to.equal(75.2)
		expect(calculateShippingReturnValue1).to.equal(95.2)
	})

	it("weight exactly zero is rejected as non-positive", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 2 (weightKg <= 0)
		const weightKg = 0;
		const zone = "Fv/2026/09/0042";
		const isPremium = true;

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight must be positive`)
	})

	it("weight far above carrier limit throws RangeError (superfluous cart arg trimmed)", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 3 (weightKg > 100)
		const weightKg = 49990;
		const zone = "@M&])%`|sbdEUgq9.y<~}fL& J##q53b-q#wL:GPW[#[W\n;#tnDleCn9K:8RiKn[Rc&bnW";
		const isPremium = false;

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight above carrier limit`)
	})

	it("negative weight rejected before other args are considered (superfluous args trimmed)", async () => {
		// SPEC.md sekcja 1: walidacja wejscia, warunek 2 (weightKg <= 0)
		const weightKg = -797;
		const zone = null;
		const isPremium = false;

		await expect((async () => {
			await calculateShipping(weightKg, zone, isPremium)
		})()).to.be.rejectedWith(`weight must be positive`)
	})

	it("non-string zone value falls through to the default rate; negative weight is rejected", async () => {
		// SPEC.md sekcja 1: stawka bazowa (inna wartosc niz "PL"/"EU" -> 79), doplata brak (<=10kg)
		// (79) * 0.8 = 63.2
		const weightKg = 3.141592653589793;
		const zone = 984.1984289538609;
		const isPremium = true;
		const calculateShippingReturnValue = await calculateShipping(weightKg, zone, isPremium)
		const weightKg1 = -709;
		const zone1 = "SoR$e){6z_8:E1'x~wh lZav§K!|";
		const isPremium1 = true;

		expect(calculateShippingReturnValue).to.equal(63.2)
		await expect((async () => {
			await calculateShipping(weightKg1, zone1, isPremium1)
		})()).to.be.rejectedWith(`weight must be positive`)
	})

	it("PL zone with >30kg surcharge and premium discount; default zone with >30kg surcharge and premium discount (superfluous arg trimmed)", async () => {
		// SPEC.md sekcja 1: (12 + 40) * 0.8 = 41.6 ; (79 + 40) * 0.8 = 95.2
		const weightKg = 99;
		const zone = "PL";
		const isPremium = true;
